import json
from docx import Document
from docx.shared import Pt,Cm,RGBColor
from docx.oxml.ns import qn
from docx.oxml import OxmlElement
r=json.load(open('results.json')); M=r['main']; me=r['meta']; mit=r['mitigation']; ci=r['cold_items']
d=Document(); s=d.sections[0]; s.page_width=Cm(21); s.page_height=Cm(29.7)
s.left_margin=s.right_margin=Cm(1.4); s.top_margin=Cm(1.0); s.bottom_margin=Cm(0.9)
st=d.styles['Normal']; st.font.name='Calibri'; st.font.size=Pt(8.3); st.element.rPr.rFonts.set(qn('w:eastAsia'),'Calibri')
st.paragraph_format.space_after=Pt(1.5); st.paragraph_format.line_spacing=1.0
def P(t,b=False,size=None):
    p=d.add_paragraph()
    for i,x in enumerate(t.split('**')):
        q=p.add_run(x); q.bold=b or i%2==1
        if size: q.font.size=Pt(size)
    return p
def H(t):
    p=P(t,True,9.3); p.paragraph_format.space_before=Pt(3); p.runs[0].font.color.rgb=RGBColor(0x1F,0x3A,0x6E)
def T(rows,w,fs=7.3):
    t=d.add_table(rows=len(rows),cols=len(w)); t.style='Table Grid'; t.autofit=False
    for i,rw in enumerate(rows):
        for j,x in enumerate(rw):
            c=t.cell(i,j); c.width=Cm(w[j]); p=c.paragraphs[0]; p.paragraph_format.space_after=Pt(0)
            for k,y in enumerate(str(x).split('**')):
                q=p.add_run(y); q.font.size=Pt(fs); q.bold=(i==0) or k%2==1
            if i==0:
                sh=OxmlElement('w:shd'); sh.set(qn('w:val'),'clear'); sh.set(qn('w:fill'),'DCE6F5'); c._tc.get_or_add_tcPr().append(sh)
    for j,x in enumerate(w): t.columns[j].width=Cm(x)
P('Самостійна робота 16 — Оцінювання рекомендаційної системи',True,12.5)
P('Курс «Сховища знань та управління знаннями» · дані: MovieTweetings (MIT; фільми+рейтинги з твітів), 921 398 рейтингів, 38 018 фільмів · студент: ________ · 12.11.2026',size=7.8)
H('1. Постановка: часовий поділ, 3 підходи, метрики (C1)')
P(f'**Часовий поділ:** межа за 80-м перцентилем часу рейтингів — **{me["T"][:10]}**: train — усе до межі ({me["n_train"]:,} рейтингів у каталозі), test — після ({me["n_test"]:,}). «Подобається» = рейтинг ≥ 8 (≈ 50% рейтингів). Каталог кандидатів — **{me["pool"]:,}** фільмів, випущених ≤ 2018 (існували на момент поділу); тестові «лайки» фільмів, випущених пізніше, не можна порекомендувати нікому, тому їх виключено (**{me["excluded_test_pos_share"]*100:.0f}%** тестових лайків). Оцінювання: **{me["warm_eval"]:,}** «теплих» користувачів (≥ 3 лайків у train і ≥ 1 новий лайк у test); побачене в train не рекомендується. **Чому не random split:** він змішує майбутнє й минуле — модель «бачить» рейтинги після моменту, який передбачає; на тих самих даних випадковий поділ дав P@5 = {r["random_split"]["Embedding (SVD, k=64)"]["P5"]:.3f} для SVD і {r["random_split"]["Популярність"]["P5"]:.3f} для популярності проти {M["Embedding (SVD, k=64)"]["P5"]:.3f} і {M["Популярність"]["P5"]:.3f} на часовому — завищення ≈ 3×.')
P('**Підходи:** (1) **Популярність** — кількість лайків у train. (2) **Content-based** — TF-IDF-вектор «28 жанрів + десятиліття», профіль користувача = нормована сума векторів лайкнутих фільмів, косинусна подібність. (3) **Embedding / граф:** **SVD** (PureSVD, k = 64, ембедінги фільмів зі зв’язного графа користувач–фільм) та **P3** (випадкове блукання користувач→фільм→користувач→фільм по двочастковому графу); окремо **гібрид** (сума z-оцінок SVD + content + популярність; без профілю — популярність) і **Random** як нижня межа. **Метрики:** Precision@5; nDCG@10 (бінарна релевантність); **Coverage@10** = частка каталогу, що потрапила хоч в один топ-10; **Novelty** = середня самоінформація −log₂(поп. частка) рекомендованих фільмів, біт; Gini експозиції та частка слотів, зайнята топ-1% фільмів; ILD — різноманітність жанрів у списку (0–1).',)
H('2. Результати (C2): часовий поділ, 3129 користувачів')
rows=[['Підхід','P@5 [95% ДІ]','nDCG@10','HR@10','Coverage@10','Novelty, біт','Gini','Топ-1% слотів','ILD']]
names=[('Популярність','Популярність'),('Content-based (жанр+десятиліття)','Content-based'),('Embedding (SVD, k=64)','Embedding SVD'),('Граф (P3, random walk)','Граф P3'),('Гібрид (SVD+content+pop)','Гібрид'),('Random','Random')]
for k,n in names:
    v=M[k]; rows.append([n,f'**{v["P5"]:.4f}** [{v["P5_ci"][0]:.4f}–{v["P5_ci"][1]:.4f}]',f'{v["nDCG10"]:.4f}',f'{v["HR10"]:.3f}',f'{v["coverage"]*100:.2f}%',f'{v["novelty"]:.1f}',f'{v["gini"]:.3f}',f'{v["top1pct_share"]*100:.0f}%',f'{v["ild"]:.2f}'])
T(rows,[3.0,3.9,1.6,1.3,2.0,1.8,1.3,1.9,1.1])
pp=r['paired']; a=pp['Embedding (SVD, k=64) - Популярність']; b=pp['Граф (P3, random walk) - Популярність']
P(f'Абсолютні значення малі (каталог 35 тис. фільмів, розріджені профілі, дрейф смаків у часі) — важливі відносні різниці. Парний bootstrap: **SVD − Популярність** ΔP@5 = +{a["P5"]:.4f} [{a["P5_ci"][0]:.4f}; {a["P5_ci"][1]:.4f}] — значуще; P3 − Популярність +{b["P5"]:.4f} [{b["P5_ci"][0]:.4f}; {b["P5_ci"][1]:.4f}] — на межі; гібрид ≈ SVD. Content-based за точністю близький до Random, але має найвище покриття ({M["Content-based (жанр+десятиліття)"]["coverage"]*100:.0f}%) і новизну — це випадкові «нішеві» фільми з однаковим жанром, а не влучні рекомендації. SVD, P3 і популярність покривають 0,2–3% каталогу: майже всі слоти займають ті самі популярні фільми.',size=8)
d.add_picture('charts.png',width=Cm(18.0))
H('3. Холодний старт (C3)')
cu=r['cold_users']
P(f'**Користувач.** У test {me["cold_users_total"]:,} користувачів без жодного рейтингу в train (≈ 3 із 4 активних у test). Для {me["cold_users_eval"]:,} із них (≥ 7 лайків) відкрито лише перші n лайків, решта (після перших 5) — істина. n = 0: усі персоналізовані моделі неможливі — **P@5 = {cu["Популярність"]["0"]["P5"]:.3f} (лише популярність)**. Вже **n = 1** SVD/P3 дають {cu["Embedding (SVD, k=64)"]["1"]["P5"]:.3f}/{cu["Граф (P3, random walk)"]["1"]["P5"]:.3f}, при **n = 3** — {cu["Embedding (SVD, k=64)"]["3"]["P5"]:.3f}/{cu["Граф (P3, random walk)"]["3"]["P5"]:.3f}, при **n = 5** — {cu["Embedding (SVD, k=64)"]["5"]["P5"]:.3f}/{cu["Граф (P3, random walk)"]["5"]["P5"]:.3f}, гібрид {cu["Гібрид (SVD+content+pop)"]["5"]["P5"]:.3f} (проти {cu["Популярність"]["5"]["P5"]:.3f} у популярності: +{(cu["Гібрид (SVD+content+pop)"]["5"]["P5"]/cu["Популярність"]["5"]["P5"]-1)*100:.0f}%). Content-based з n ≥ 1 **гірший за популярність** ({cu["Content-based (жанр+десятиліття)"]["1"]["P5"]:.3f}–{cu["Content-based (жанр+десятиліття)"]["5"]["P5"]:.3f}): лише жанр+десятиліття — надто бідні ознаки. **Як вирішено:** (1) n = 0 → fallback на популярність; (2) n ≥ 1 → fold-in профілю у SVD/P3; (3) гібрид, у якому популярність гасить шум content-сигналу.')
P(f'**Фільм.** {ci["n_cold_items"]:,} фільмів каталогу не мають жодного рейтингу в train, але отримують **{ci["share_of_test_positives"]*100:.0f}%** нових лайків теплих користувачів. SVD, P3 і популярність не можуть їх порекомендувати (оцінка 0, випадковий вибір: P@5 ≈ {ci["Популярність"]["P5"]:.4f}, HR@10 ≈ {ci["Популярність"]["HR10"]:.3f}); content-based за ознаками жанру має P@5 = **{ci["Content-based (жанр+десятиліття)"]["P5"]:.4f}**, HR@10 = **{ci["Content-based (жанр+десятиліття)"]["HR10"]:.3f}** серед {ci["users"]:,} користувачів — ≈ 10–35× краще за випадковість (випадково {ci["Random"]["P5"]:.4f} / {ci["Random"]["HR10"]:.3f}). Тож content-ознаки корисні саме для нових фільмів, колаборативні — для нових користувачів з кількома лайками.',size=8)
H('4. Етичні ризики та заходи (C4)')
T([['#','Ризик','Що виміряно тут','Заходи'],
['1','**Упередження популярності / петля зворотного зв’язку.** Система показує лише популярне → воно стає ще популярнішим, ніша зникає',f'SVD: coverage {M["Embedding (SVD, k=64)"]["coverage"]*100:.1f}%, топ-1% фільмів = {M["Embedding (SVD, k=64)"]["top1pct_share"]*100:.1f}% слотів, Gini {M["Embedding (SVD, k=64)"]["gini"]:.3f}',f'Штраф за популярність у ранжуванні: λ=3 → coverage {mit["3"]["coverage"]*100:.1f}% (×{mit["3"]["coverage"]/mit["0"]["coverage"]:.0f}), novelty {mit["0"]["novelty"]:.1f}→{mit["3"]["novelty"]:.1f} біт, але P@5 {mit["0"]["P5"]:.4f}→{mit["3"]["P5"]:.4f} (−{(1-mit["3"]["P5"]/mit["0"]["P5"])*100:.0f}%); λ=1.5: coverage {mit["1.5"]["coverage"]*100:.1f}% без втрати P@5. Квоти експозиції, exploration, моніторинг Gini/coverage'],
['2','**Фільтр-бульба.** Вузький жанровий профіль → дедалі однотипні рекомендації',f'Content-based: ILD {M["Content-based (жанр+десятиліття)"]["ild"]:.2f} проти {M["Embedding (SVD, k=64)"]["ild"]:.2f} у SVD — списки майже одного жанру',f'MMR/діверсифікація, quota «не менше 3 жанрів у топ-10», перемикач «здивуй мене», пояснення («бо ви лайкнули…»), можливість скинути історію. Штраф λ=3 піднімає ILD {mit["0"]["ild"]:.2f}→{mit["3"]["ild"]:.2f}'],
['3','**Конфіденційність і згода.** Користувацькі id = ідентифікатори Twitter; історія переглядів чутлива, їх можна деанонімізувати',f'{me["train_users"]:,} користувачів у train; рейтинги публічні в твітах, але зібрані без їхньої згоди на рекомендації','Псевдонімізація/хешування, мінімізація (зберігати лише те, що потрібно), право на видалення (GDPR), не поєднувати з зовнішніми профілями, диференційна приватність/агрегація для звітів'],
['4','**Нерівність для нових користувачів і нових фільмів; упередженість вибірки.** Дані — лише з твітів про фільми, мова/регіон/вік імовірно зміщені (не вимірювалось); новинки без рейтингів не рекомендуються',f'{me["cold_users_total"]:,} нових користувачів отримують лише популярне; {ci["n_cold_items"]:,} нових фільмів дають {ci["share_of_test_positives"]*100:.0f}% лайків, але колаборативні моделі їх не бачать','Fallback + швидкий онбординг (2–3 лайки), content-ознаки для новинок, окреме звітування метрик за групами (холодні/теплі), захист від накрутки рейтингів']],[0.5,5.0,5.2,7.2],fs=7)
H('5. Самоперевірка')
P('**Чому random split хибний?** Він використовує «майбутні» дані для навчання і завищує якість (тут ≈ 3×), а в продакшені передбачаємо майбутнє. **Що таке coverage?** Частка каталогу, яку система хоч раз рекомендувала (тут SVD — 1%, content — 21%); висока точність при низькому coverage = монополія популярного. **Як розв’язано холодний старт?** Fallback на популярність при n = 0, fold-in профілю при n ≥ 1, content-ознаки для нових фільмів, гібрид. **Ризики бульби та пом’якшення:** вузька експозиція й однотипні жанри (ILD, coverage, Gini) → діверсифікація, штраф за популярність, квоти, контроль користувача.',size=8)
H('6. Декларація ШІ та обмеження')
P('**Моделі:** claude-sonnet-5-5 (асистент: код, розрахунки, текст; налаштований ідентифікатор — фактична модель могла відрізнятися). Мета: реалізація 3+ підходів, метрик і звіту. Приклад запиту: «реалізуй popularity / content-based / SVD / P3, часовий поділ за перцентилем, P@5, nDCG@10, coverage, novelty; проаналізуй холодний старт». **Перевірка:** код запущено, результати збережено в results.json; випадковий поділ як контроль завищення; довірчі інтервали bootstrap по користувачах. **Обмеження:** одна межа поділу, одне зерно; гіперпараметри (k = 64, поріг ≥ 8, λ, ваги гібрида) не налаштовувались; 40% тестових лайків (фільми після 2018) виключено; content-based лише на жанрі+десятилітті; Novelty рахується за train-популярністю; етичні ризики оцінено за метриками офлайн, без користувацького дослідження; джерело даних (твіти) імовірно зміщене. Вихідні дані завантажено з GitHub (MovieTweetings, MIT) — перевірте джерело самі.',size=7.6)
